function getStats(pool:Player[]){ const out={} as Record<keyof Metrics,{mean:number;sd:number;min:number;max:number}>; METRICS.forEach(({key})=>{ const vals=pool.map(p=>p.m[key]); const mean=vals.reduce((a,b)=>a+b,0)/vals.length; const sd=Math.sqrt(vals.reduce((a,b)=>a+(b-mean)**2,0)/vals.length)||1; out[key]={mean,sd,min:Math.min(...vals),max:Math.max(...vals)}; }); return out; }
